// events: before insert, before update, before delete,
//         after insert, after update, after delete, after undelete

trigger AccountDeletion on Account (before delete) {
    for (Account a : [SELECT Id FROM Account
                      WHERE Id IN (SELECT AccountId FROM Opportunity)
                      AND Id IN :Trigger.old]) {
        Trigger.oldMap.get(a.Id).addError('Opportunity가 있는 Account는 삭제할 수 없습니다.');
    }
}

public class CalloutQueueable implements Queueable, Database.AllowsCallouts {
